<script lang="ts">
	import { enhance } from '$app/forms';
	import { read_contact, validate_contact, type ContactErrors } from '#lib/contact.ts';
	import type { PageProps } from './$types';

	let { form }: PageProps = $props();

	/** Errors found in the browser, which stop the form from being sent. */
	let client_errors = $state<ContactErrors | null>(null);

	const errors: ContactErrors = $derived(client_errors ?? form?.errors ?? {});
	const values = $derived(form?.values);
	const sent_to = $derived(!client_errors && form?.success ? form.name : null);
</script>

<svelte:head>
	<title>Contact | Bookshelf</title>
</svelte:head>

<h1>Contact</h1>

{#if sent_to !== null}
	<p role="status">Thanks, {sent_to}! Your message has been sent.</p>
{/if}

<form
	method="POST"
	novalidate
	use:enhance={({ formData, cancel }) => {
		const found = validate_contact(read_contact(formData));
		if (Object.keys(found).length > 0) {
			client_errors = found;
			cancel();
			return;
		}
		client_errors = null;
	}}
>
	<div class="field">
		<label for="name">Name</label>
		<input
			id="name"
			name="name"
			type="text"
			autocomplete="name"
			value={values?.name ?? ''}
