// Starts the production server built by adapter-node (`build/index.js`).
//
// adapter-node no longer reads `ORIGIN`: it derives each request's origin from
// the `host` header and assumes `https` unless a protocol header says otherwise.
// Served over plain http, that origin never matches the browser's `Origin`
// header, and SvelteKit's CSRF check rejects every form submission. So the
// protocol is taken from `ORIGIN` (falling back to `http`) and passed in a
// header that this wrapper always sets itself, so clients cannot spoof it.
import process from 'node:process';

const PROTOCOL_HEADER = 'x-bookshelf-protocol';
const origin = process.env.ORIGIN ? new URL(process.env.ORIGIN) : null;
const protocol = origin ? origin.protocol.slice(0, -1) : 'http';

process.env.PROTOCOL_HEADER = PROTOCOL_HEADER;

const { server } = await import('./build/index.js');

server.prependListener('request', (req) => {
	req.headers[PROTOCOL_HEADER] = protocol;

	// A same-site browser always sends `Origin` with a form POST; other clients
	// (scripts, tests) may not, and are not what CSRF protection guards against.
	if (origin && req.method === 'POST' && !req.headers.origin) {
		req.headers.origin = `${protocol}://${req.headers.host ?? origin.host}`;
	}
});
EOF
